{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 12,
      "verse": 21,
      "text_ar": "ومنهم اثنان يهلكان حين يدنو نصف الأيام. وأربعة يحفظون مدّةً حتى يدنو وقت نهاية الأمر. لكن اثنَيْن يحفظان حتى النهاية.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 22,
      "text_ar": "قد رأيت رؤوس ثلاثة راكدةً. هذا هو التفسير:",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 23,
      "text_ar": "في أيامها الأخيرة يقيمُ العليّ ثلاثَ ممالك، ويُجدِّدُ فيهنَّ أشياءَ كثيرة. فإنَّهنَّ سيدنّ على الأرض",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 24,
      "text_ar": "وعلى الساكنين فيها، بكثيرٍ من الظلمِ أكثرَ ممَّن كانوا قبلَهنّ. ولذلك تُدعى رؤوسَ النسر.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 25,
      "text_ar": "فإنَّهنَّ هنَّ اللواتي يُثِمْنَ فجورَها، ويُنجزنَ أفعالَها الأخيرة.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 26,
      "text_ar": "لقد رأيتَ أنَّ الرأسَ الكبيرَ أخفى. هذا إشارةٌ إلى أنَّ واحداً منهما يموتُ على سريره، ومع ذلك بشدّةٍ ومِحنة.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 27,
      "text_ar": "أمّا الحيَّانِ الباقيانِ، فاسحقهما السيفُ.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 28,
      "text_ar": "فإنَّ سيفَ الواحدِ يبتلعُ الذي كان معَه، لكنه يقعُ أيضاً بالسيفِ في الأيام الأخيرة.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 29,
      "text_ar": "رأيْتَ اثنينِ تحتِ جناحينِ يمرَّانِ إلى الرأسِ الذي على الجانب الأيمن.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 30,
      "text_ar": "هذا هو التفسير: هذان هما اللذانِ حفِظَهما العليّ حتى نهايةِ أيّامِه. هذا هو المُلكُ القصيرُ الذي كان مملوءَاً بالصِّراع، كما رأيت.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 31,
      "text_ar": "«أما الأسدُ الذي رأيْتَه يقفُ من الغابةِ، ويهطمُ، ويأنفُ على النسر، ويوبّخُها على ظلمِها، وعلى كلّ كلامِها الذي سمعتَ",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 32,
      "text_ar": "فهذا هو الممسوحُ الذي حفِظَهُ العليّ حتى النهاية [من الأيامِ، ومَن هو ممّنْ هو بزُرْعِ داود، فيقومُ ويأتي] ويكلّمُهم ويوبِّخهم على شرِّهم وظلمِهم، ويكدِّسُ قدامَهُم أفعالَهم المُستَهزِئةَ.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 33,
      "text_ar": "لأنَّه في أوّلِ الأمرِ يقيمُهم في حُكمِه، وحينَ يُوبِّخُهم يبيدُهم.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 34,
      "text_ar": "لأنَّه يخلِّصُ فائِتي شعبيِ برأفةٍ، الذينِ حصُنوا في كلّ حدودي، ويسرُّهم حتى مجيءِ النهايةِ، أي يومِ القضاءِ الذي حدّثتُكم عنهُ منذِ البدايةِ.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 35,
      "text_ar": "هذا هو الرؤيا التي رأيتَها، وهذا هو تفسيرُها.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 36,
      "text_ar": "لكنَّكَ أنتَ استحقَّتَ أن تعرفَ سرَّ العليِّ.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 37,
      "text_ar": "لذلك اكتبِ كلَّ ما رأيته في كتابٍ، وضعْهُ في مكانٍ خفيٍّ.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 38,
      "text_ar": "وحِبّها إلى حكماءِ قومِكَ الذينَ تعرفُ قلوبَهم أنهم قادرون على استيعاب هذه الأسرار وحفظِها.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 39,
      "text_ar": "لاكنك انتظر ا هناً سبعةَ أيامٍ أخرى، لكي يُرِيَكَ ما يُريدُ العليُّ أن يُريَه». فمضى من عندي.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 40,
      "text_ar": "وحدث أنه حين رآى جميعُ الناس أنّ الأيام السبعة قد انقضت، ولم أكن قد رجعتُ إلى المدينةِ مرةً أخرى، اجتمعوا جميعُهم من الصغيرِ إلى الكبيرِ، وأتوا إليّ وتكلّموا معي قائلين:",
      "review_notes_ar": []
    }
  ]
}
